import {Intelligence, type Prediction, type Scenario} from './Intelligence';
import { useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowRight, BookOpen, Check, ChevronLeft, ChevronRight, CircleHelp, LockKeyhole, Plus, Search, Shield, Swords, Target, Trash2, Users, Wallet } from 'lucide-react';

export type Customer = { id: string; name: string; email: string; note: string };
export type Project = { id: string; name: string; customerId: string; stage: string; budget: number; currency: string; note: string };
export type SavingsGoal = { id: string; name: string; target: number; saved: number; currency: string };
export type SpendingBudget = { id: string; name: string; amount: number; currency: string; period: 'month' | 'all-time' };
export type TrainingAttribute = 'Strength' | 'Endurance' | 'Agility' | 'Discipline' | 'Reaction' | 'Focus' | 'Technique' | 'General';
export type TrainingChallenge = { id: string; title: string; kind: 'safe' | 'boss'; attribute?: TrainingAttribute; description: string; target: number; progress: number; linkedQuestId: string; completedAt?: string };
export type LessonProgress = { reviewed: boolean; mastered: boolean; correct: number; attempts: number; completedAt?: string };
export type PhaseTwoData = {
  customers: Customer[];
  projects: Project[];
  goals: SavingsGoal[];
  budgets: SpendingBudget[];
  training: TrainingChallenge[];
  lessons: Record<string, LessonProgress>;
  socialCompletions: string[];
  predictions?: Prediction[];
  scenarios?: Scenario[];
};
export const emptyPhaseTwo = (): PhaseTwoData => ({ customers: [], projects: [], goals: [], budgets: [], training: [], lessons: {}, socialCompletions: [], predictions: [], scenarios: [] });

export function validPhaseTwo(value: unknown): value is PhaseTwoData {
  if (!value || typeof value !== 'object') return false;
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v.customers) || !Array.isArray(v.projects) || !Array.isArray(v.goals) || (v.budgets !== undefined && !Array.isArray(v.budgets)) || !Array.isArray(v.training) || !v.lessons || typeof v.lessons !== 'object' || Array.isArray(v.lessons) || !Array.isArray(v.socialCompletions)) return false;
  const currencies = ['ZAR','USD','EUR','GBP'];
  const validDate = (x: unknown) => typeof x === 'string' && Number.isFinite(Date.parse(x));
  return v.customers.every((x: any) => x && typeof x.id === 'string' && typeof x.name === 'string' && typeof x.email === 'string' && typeof x.note === 'string')
    && v.projects.every((x: any) => x && typeof x.id === 'string' && typeof x.name === 'string' && typeof x.customerId === 'string' && ['lead', 'discovery', 'proposal', 'active', 'complete', 'paused'].includes(x.stage) && Number.isFinite(x.budget) && x.budget >= 0 && currencies.includes(x.currency) && typeof x.note === 'string')
    && v.goals.every((x: any) => x && typeof x.id === 'string' && typeof x.name === 'string' && Number.isFinite(x.target) && x.target > 0 && Number.isFinite(x.saved) && x.saved >= 0 && currencies.includes(x.currency))
    && (v.budgets === undefined || (v.budgets as any[]).every((x: any) => x && typeof x.id === 'string' && typeof x.name === 'string' && Number.isFinite(x.amount) && x.amount > 0 && currencies.includes(x.currency) && ['month','all-time'].includes(x.period)))
    && v.training.every((x: any) => x && typeof x.id === 'string' && typeof x.title === 'string' && ['safe', 'boss'].includes(x.kind) && (x.attribute === undefined || ['Strength','Endurance','Agility','Discipline','Reaction','Focus','Technique','General'].includes(x.attribute)) && typeof x.description === 'string' && Number.isFinite(x.target) && x.target > 0 && Number.isFinite(x.progress) && x.progress >= 0 && x.progress <= x.target && typeof x.linkedQuestId === 'string' && (x.completedAt === undefined || validDate(x.completedAt)))
    && Object.values(v.lessons as Record<string, any>).every((x: any) => x && typeof x.reviewed === 'boolean' && typeof x.mastered === 'boolean' && Number.isFinite(x.correct) && x.correct >= 0 && Number.isFinite(x.attempts) && x.attempts >= x.correct && (x.completedAt === undefined || validDate(x.completedAt)))
    && v.socialCompletions.every(x => typeof x === 'string')
    && (v.predictions === undefined || (Array.isArray(v.predictions) && v.predictions.every((x:any)=>x && typeof x.id==='string' && typeof x.goal==='string' && typeof x.evidence==='string' && typeof x.assumptions==='string' && typeof x.recommendation==='string' && typeof x.createdAt==='string' && (x.actual===undefined || typeof x.actual==='string'))))
    && (v.scenarios === undefined || (Array.isArray(v.scenarios) && v.scenarios.every((x:any)=>x && typeof x.id==='string' && typeof x.title==='string' && typeof x.optionA==='string' && typeof x.optionB==='string' && [x.costA,x.costB,x.benefitA,x.benefitB].every((n:unknown)=>typeof n==='number' && Number.isFinite(n) && n>=0) && typeof x.createdAt==='string')));
}
export function normalizePhaseTwo(value: unknown): PhaseTwoData {
  if (validPhaseTwo(value)) return { ...emptyPhaseTwo(), ...value, budgets: value.budgets || [], training: value.training.map(challenge => ({ ...challenge, attribute: challenge.attribute || 'General' })) };
  return emptyPhaseTwo();
}

type SkillRef = { id: string; name: string; xp: number };
type MoneyEntry = { id: string; amount: number; currency: string; type: 'income' | 'expense'; category: string; note: string; at: string };
type QuestRef = { id: string; title: string; status: string };
type Props = {
  value: PhaseTwoData; onChange: (next: PhaseTwoData) => void;
  transactions: MoneyEntry[]; onTransaction: (value: Omit<MoneyEntry, 'id' | 'at'>) => void;
  currencies: string[]; skills: SkillRef[]; quests: QuestRef[];
  onLessonXp: (word: string, amount: number) => void; onTrainingComplete: (questId: string) => void;
};

const words = [
  {word:'Intention', definition:'A purpose or aim held in mind before or while acting.', roots:'Old French intentionem, from Latin intendere: to stretch out or turn attention toward.', history:'The Latin noun described a stretching or directing of the mind. English retained the sense of a purpose aimed toward an outcome.', practical:'Name the direction you mean to move in; it can guide a choice without guaranteeing its result.', application:'Write one sentence describing what matters in your next work session.', example:'“My intention is to listen before I answer.”', exercise:'Choose one modest action today and write the purpose behind it.', question:'What does intention help you clarify?', answer:'The purpose or direction behind an action.', xp:15},
  {word:'Attention', definition:'The deliberate or receptive directing of awareness toward something.', roots:'Latin attentionem / attendere, ad + tendere: stretch toward.', history:'The Latin idea of stretching toward developed into the English sense of noticing, care, and focused awareness.', practical:'Attention decides what information you take in; it can be guided, rested, and redirected.', application:'Remove one distraction for a short chosen period.', example:'“I gave the conversation my attention instead of checking my phone.”', exercise:'For two minutes, notice a task without switching to another one.', question:'What image sits behind the Latin root?', answer:'Stretching toward something.', xp:15},
  {word:'Belief', definition:'A view accepted as true, or confidence placed in a person or idea.', roots:'Middle English from West Germanic *ga-laubon, to hold dear, esteem, or trust; related to PIE *leubh-, care / desire / love.', history:'The word’s early family connects trust and esteem. Modern belief can describe conviction, assumption, or religious faith.', practical:'Treat beliefs as ideas you can examine; confidence is not proof.', application:'Ask what evidence supports a belief and what might change your mind.', example:'“I believe practice can improve this skill because I have seen gradual progress.”', exercise:'Write one helpful belief and one observation that supports it.', question:'Which older sense is associated with the word family?', answer:'To hold dear, esteem, or trust.', xp:15},
  {word:'Command', definition:'A clear direction, instruction, or ability to guide an action.', roots:'Via Old French comander and Vulgar Latin *commandare; related to Latin commendare (entrust / recommend), shaped by mandare (commit / entrust).', history:'The word moved through Romance forms associated with entrusting and directing, later taking the English senses of order and mastery.', practical:'A command can be a clear instruction to yourself or another, offered with context and respect.', application:'Turn a vague goal into one specific next instruction.', example:'“Set a ten-minute timer and draft the opening paragraph.”', exercise:'Give yourself one concrete, kind instruction for a task.', question:'Does the history support a “with + hand” derivation?', answer:'No; the documented path is through forms meaning entrust / recommend and commit / entrust.', xp:15},
  {word:'Discipline', definition:'A field of learning, or the practiced structure that supports chosen work.', roots:'Latin disciplina, instruction / teaching / learning, from discipulus, pupil.', history:'Its early meanings centered on teaching and study. English later developed senses of training, order, and self-regulation.', practical:'Useful discipline is a repeatable support, not punishment or a measure of worth.', application:'Make a task easier to begin by choosing a time, place, and first step.', example:'“I keep my writing notes beside the chair where I work.”', exercise:'Design a small routine that reduces friction for one valued action.', question:'What does discipulus mean?', answer:'Pupil.', xp:15},
  {word:'Influence', definition:'The capacity to affect a course, choice, or condition.', roots:'Medieval Latin influentia, “flowing in,” from Latin influere, flow into.', history:'An image of an inward flow broadened into the power to shape events or choices. It does not imply total control.', practical:'Notice the conditions that shape you and the limited ways you may shape conditions in turn.', application:'Change one environmental cue that supports your chosen behavior.', example:'“A quiet desk influences how easily I begin.”', exercise:'Name one influence you can adjust and one you cannot control.', question:'What image appears in the Medieval Latin source?', answer:'Flowing in.', xp:15},
  {word:'Persuasion', definition:'Communication intended to invite another person to consider a view or action.', roots:'Latin persuasio / persuadere; per, thoroughly + suadere, urge or persuade; ultimately PIE *swād-, sweet / pleasant.', history:'The Latin construction emphasized urging thoroughly. Modern persuasion spans reasoned advocacy and less ethical pressure, so context matters.', practical:'Ethical persuasion is transparent, evidence-aware, and leaves room for refusal.', application:'State your reason, acknowledge uncertainty, and invite a genuine response.', example:'“Here is why I think this plan may help; what concerns do you see?”', exercise:'Practice making a request without hiding its purpose or consequences.', question:'What does suadere contribute?', answer:'To urge or persuade.', xp:15},
  {word:'Strategy', definition:'A considered approach for coordinating actions toward a chosen aim.', roots:'French / Latinized Greek strategia, office or command of a general, from strategos, general / army commander.', history:'The term began in the domain of leadership and planning, then broadened to organized approaches in many fields.', practical:'A strategy connects a goal to choices and trade-offs; it should adapt when evidence changes.', application:'Choose a goal, one likely obstacle, and a fallback action.', example:'“I will prepare the outline first and reserve Friday for revision.”', exercise:'Draft a three-step plan with one flexible alternative.', question:'What was strategia associated with?', answer:'The office or command of a general.', xp:15},
  {word:'Perception', definition:'The way sensory information or ideas are noticed and interpreted.', roots:'Latin perceptionem / perceptio from percipere, perceive or take in.', history:'The Latin sense of taking in developed into the English process of noticing, understanding, and interpreting.', practical:'Perception is an interpretation, not always the whole picture; checking assumptions can help.', application:'Separate what you observed from the meaning you assigned to it.', example:'“They paused” is an observation; “they disliked my idea” is an interpretation.', exercise:'Write one observation and two possible interpretations of it.', question:'What does percipere mean?', answer:'To perceive or take in.', xp:15},
  {word:'Opportunity', definition:'A circumstance or time that may make an action possible or favorable.', roots:'Latin opportunitas, fitness / convenience / favorable time. Etymonline connects it to ob portum veniens, “coming toward a port,” a historical image of favorable wind.', history:'The port-and-wind explanation is a memorable historical account, not a certain literal derivation. The broader sense is a favorable or suitable occasion.', practical:'An opportunity is a possibility, not a promise; weigh its fit, cost, and timing.', application:'Identify one opening and the smallest safe way to explore it.', example:'“The free evening is an opportunity to test a short lesson.”', exercise:'List one possible opportunity and one condition you would check first.', question:'How should the port explanation be presented?', answer:'As a historical explanation connected by the source, not a certain literal derivation.', xp:15},
  {word:'Action', definition:'The process of doing something; an act or step taken.', roots:'Latin actio from agere, do / drive / move.', history:'The Latin family of doing and moving formed a broad English word for acts, processes, and influence.', practical:'Action turns a chosen intention into observable behavior, however small.', application:'Define the next physical step rather than only the desired result.', example:'“Open the document and write a heading” is an action.', exercise:'Choose one task and specify its first two-minute action.', question:'What is the root sense of agere?', answer:'Do, drive, or move.', xp:15},
  {word:'Consistency', definition:'The quality of being coherent or continuing in a steady way.', roots:'Medieval Latin consistentia, “standing together,” from consistere, stand firm; connected to PIE *sta-, stand.', history:'The word developed from an image of things standing together into agreement and steadiness over time.', practical:'Consistency is a pattern that can include pauses and renewed starts; it is not a perfect streak.', application:'Choose a manageable version of an effort that can resume after interruptions.', example:'“I returned to the course after a busy week.”', exercise:'Set a small repeatable action with no penalty for missing a day.', question:'What image is present in consistentia?', answer:'Standing together.', xp:15},
  {word:'Confidence', definition:'Trust in a person, process, or one’s capacity in a particular situation.', roots:'Latin confidentia from confidere, trust / rely; fidere means trust and is linked to PIE *bheidh-.', history:'The family of trust and reliance gave English confidence as assurance or belief in ability, often grounded by experience.', practical:'Confidence can grow through preparation and evidence; it need not mean certainty.', application:'Record one skill you can rely on and one support you can use.', example:'“I am confident I can ask for clarification, even if I feel nervous.”', exercise:'Recall one time preparation helped you handle an unfamiliar task.', question:'What does fidere mean?', answer:'Trust.', xp:15},
  {word:'Negotiation', definition:'A discussion in which people seek an agreement or workable arrangement.', roots:'Latin negotiatio via negotium, business / work, literally “lack of leisure”: neg- + otium. The origin of otium is unknown.', history:'The Latin word for business developed into the English process of discussing terms and reaching an arrangement.', practical:'Healthy negotiation makes needs, constraints, and alternatives explicit; agreement is not always possible.', application:'Prepare what matters, what can change, and what would make you pause.', example:'“Could we adjust the deadline if I deliver the first section today?”', exercise:'Practice a request that names both your need and a possible alternative.', question:'What does negotium literally express?', answer:'Lack of leisure; the origin of otium is unknown.', xp:15},
  {word:'Decision', definition:'A choice made after considering options, or the act of reaching that choice.', roots:'Latin decisio from decidere, cut off; de, off + caedere, cut.', history:'The image of cutting off alternatives developed into the act of settling a question or choosing a course.', practical:'A decision can be provisional. Naming a review point can reduce pressure to be certain forever.', application:'Compare options against a criterion you actually value.', example:'“I will try this schedule for two weeks, then review.”', exercise:'Make one small reversible decision and set a date to revisit it.', question:'What image lies in decidere?', answer:'Cutting off alternatives.', xp:15},
];

const fieldStyle = { width:'100%', minHeight:38, padding:'8px 10px', color:'#e5e2d8', border:'1px solid #3d424b', borderRadius:7, background:'#13161c', fontSize:11 } as const;
const makeId = () => crypto.randomUUID();
const card = { border:'1px solid #2d323b', borderRadius:12, background:'#191c23', padding:18 } as const;
const primary = { color:'#211d14', background:'#d7b96e', border:'1px solid #e1c77f', borderRadius:7, padding:'9px 13px', fontSize:11, fontWeight:700, cursor:'pointer' } as const;
const secondary = { color:'#d8d5cb', background:'#1b1e25', border:'1px solid #373c45', borderRadius:7, padding:'8px 11px', fontSize:10, cursor:'pointer' } as const;
const heading = { fontFamily:'var(--app-font-serif)', fontWeight:500, color:'#e9e6dc' } as const;
function Section({title, eyebrow, children, actions}:{title:string;eyebrow:string;children:ReactNode;actions?:ReactNode}) {
  return <section style={{...card, marginBottom:14}}><div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:12,marginBottom:15}}><div><div className="eyebrow">{eyebrow}</div><h2 style={{...heading,fontSize:23,margin:'5px 0 0'}}>{title}</h2></div>{actions}</div>{children}</section>;
}

export function PhaseTwoWorld({value,onChange,transactions,onTransaction,currencies,skills,quests,onLessonXp,onTrainingComplete}:Props) {
  const [tab,setTab]=useState<'business'|'english'|'training'|'social'|'intelligence'>('business');
  return <div>
    <div className="phase2-tabs" role="tablist" aria-label="World modules">{[
      ['business','Manual business',Wallet],['english','English Magick',BookOpen],['training','Training',Target],['social','Social practice',Users],['intelligence','Oracle & Decisions',CircleHelp],
    ].map(([key,label,Icon]:any)=><button type="button" role="tab" aria-selected={tab===key} className={tab===key?'active':''} onClick={()=>setTab(key)} key={key} data-testid={`tab-phase2-${key}`}><Icon size={15}/>{label}</button>)}</div>
    {tab==='business'&&<Business value={value} onChange={onChange} transactions={transactions} onTransaction={onTransaction} currencies={currencies}/>}
    {tab==='english'&&<English value={value} onChange={onChange} onLessonXp={onLessonXp}/>}
    {tab==='training'&&<Training value={value} onChange={onChange} quests={quests} onTrainingComplete={onTrainingComplete}/>}
    {tab==='social'&&<Social value={value} onChange={onChange}/>}
    {tab==='intelligence'&&<Intelligence predictions={value.predictions||[]} scenarios={value.scenarios||[]} onPredictions={predictions=>onChange({...value,predictions})} onScenarios={scenarios=>onChange({...value,scenarios})}/>}
  </div>;
}

function Business({value,onChange,transactions,onTransaction,currencies}:Pick<Props,'value'|'onChange'|'transactions'|'onTransaction'|'currencies'>) {
  const [form,setForm]=useState<'customer'|'project'|'goal'|'budget'|'money'|null>(null);
  const [edit,setEdit]=useState<string|null>(null);
  const [notice,setNotice]=useState('');
  const [customerName,setCustomerName]=useState(''); const [email,setEmail]=useState(''); const [note,setNote]=useState('');
  const [projectName,setProjectName]=useState(''); const [customerId,setCustomerId]=useState(''); const [stage,setStage]=useState('lead'); const [budget,setBudget]=useState(''); const [currency,setCurrency]=useState(currencies[0]||'ZAR');
  const [goalName,setGoalName]=useState(''); const [target,setTarget]=useState(''); const [saved,setSaved]=useState('');const [budgetCategory,setBudgetCategory]=useState('');const [budgetLimit,setBudgetLimit]=useState('');const [budgetPeriod,setBudgetPeriod]=useState<'month'|'all-time'>('month'); const [moneyType,setMoneyType]=useState<'income'|'expense'>('income'); const [moneyAmount,setMoneyAmount]=useState(''); const [category,setCategory]=useState('');
  const stages=['lead','discovery','proposal','active','complete','paused'];
  const profit=useMemo(()=>currencies.map(c=>({currency:c,net:transactions.filter(t=>t.currency===c).reduce((n,t)=>n+(t.type==='income'?t.amount:-t.amount),0),income:transactions.filter(t=>t.currency===c&&t.type==='income').reduce((n,t)=>n+t.amount,0),expense:transactions.filter(t=>t.currency===c&&t.type==='expense').reduce((n,t)=>n+t.amount,0)})),[currencies,transactions]);
  const patch=(key:keyof PhaseTwoData,items:any[])=>onChange({...value,[key]:items});
  const start=(kind:typeof form,item?:any)=>{setEdit(item?.id||null);setForm(kind);setCustomerName(item?.name||'');setEmail(item?.email||'');setNote(item?.note||'');setProjectName(item?.name||'');setCustomerId(item?.customerId||value.customers[0]?.id||'');setStage(item?.stage||'lead');setBudget(String(item?.budget||''));setCurrency(item?.currency||currencies[0]||'ZAR');setGoalName(item?.name||'');setTarget(String(item?.target||''));setSaved(String(item?.saved||''));setBudgetCategory(item?.name||'');setBudgetLimit(String(item?.amount||''));setBudgetPeriod(item?.period||'month');setMoneyAmount('');setCategory('');};
  const save=(e:FormEvent)=>{e.preventDefault();if(form==='customer'){const c={id:edit||makeId(),name:customerName.trim(),email:email.trim(),note:note.trim()};patch('customers',edit?value.customers.map(x=>x.id===edit?c:x):[c,...value.customers]);}
    if(form==='project'){const p={id:edit||makeId(),name:projectName.trim(),customerId,stage,budget:Number(budget)||0,currency,note:note.trim()};patch('projects',edit?value.projects.map(x=>x.id===edit?p:x):[p,...value.projects]);}
    if(form==='goal'){const g={id:edit||makeId(),name:goalName.trim(),target:Number(target),saved:Number(saved)||0,currency};patch('goals',edit?value.goals.map(x=>x.id===edit?g:x):[g,...value.goals]);}
     if(form==='budget'){const b={id:edit||makeId(),name:budgetCategory.trim(),amount:Number(budgetLimit),currency,period:budgetPeriod};patch('budgets',edit?value.budgets.map(x=>x.id===edit?b:x):[b,...value.budgets]);}
    if(form==='money'){onTransaction({amount:Number(moneyAmount),currency,type:moneyType,category:category.trim(),note:note.trim()});}
    setForm(null);setEdit(null);setNotice('Saved on this device.');window.setTimeout(()=>setNotice(''),2300);};
  const remove=(kind:'customers'|'projects'|'goals'|'budgets',id:string)=>{if(!window.confirm('Remove this record from your local business dashboard?'))return;if(kind==='customers')onChange({...value,customers:value.customers.filter(x=>x.id!==id),projects:value.projects.map(x=>x.customerId===id?{...x,customerId:''}:x)});else patch(kind,(value[kind] as any[]).filter(x=>x.id!==id));};
  const spent=(budget:SpendingBudget)=>transactions.filter(t=>t.type==='expense'&&t.currency===budget.currency&&t.category.trim().toLowerCase()===budget.name.trim().toLowerCase()&&(budget.period==='all-time'||(()=>{const date=new Date(t.at);const now=new Date();return date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()})())).reduce((sum,t)=>sum+t.amount,0);
  return <div>
    <div className="phase2-note"><LockKeyhole size={15}/> All figures are entered by you. Currency cards show the net of all ledger income and expenses you have logged (not just business-tagged records); no exchange rates, automatic imports, accounting advice, or forecast are included.</div>
    <div className="phase2-money-grid">{profit.map(x=><div className="phase2-money" key={x.currency}><span>{x.currency} · LOGGED NET</span><b>{new Intl.NumberFormat(undefined,{style:'currency',currency:x.currency}).format(x.net)}</b><small>Revenue {x.income.toFixed(2)} · expenses {x.expense.toFixed(2)}</small></div>)}</div>
    <Section title="Customers" eyebrow="YOUR CONTACTS" actions={<button style={primary} onClick={()=>start('customer')}><Plus size={14}/> Add customer</button>}>
      {value.customers.length?<div className="phase2-record-grid">{value.customers.map(c=><article className="phase2-record" key={c.id}><div><b>{c.name}</b><small>{c.email||'No email recorded'}</small><p>{c.note||'No notes yet.'}</p></div><div className="phase2-row-actions"><button style={secondary} onClick={()=>start('customer',c)}>Edit</button><button style={secondary} aria-label={`Delete ${c.name}`} onClick={()=>remove('customers',c.id)}><Trash2 size={14}/></button></div></article>)}</div>:<div className="phase2-empty"><Users size={20}/><b>Your customer list starts here.</b><span>Keep only the details you choose to record.</span></div>}
    </Section>
    <Section title="Projects & sales stages" eyebrow="MANUAL PIPELINE" actions={<button style={primary} onClick={()=>start('project')}><Plus size={14}/> Add project</button>}>
      {value.projects.length?<div className="phase2-record-grid">{value.projects.map(p=><article className="phase2-record" key={p.id}><div><b>{p.name}</b><small>{value.customers.find(c=>c.id===p.customerId)?.name||'No linked customer'} · {p.stage}</small><p>{p.note||'Budget entered: '+new Intl.NumberFormat(undefined,{style:'currency',currency:p.currency}).format(p.budget)}</p></div><div className="phase2-row-actions"><button style={secondary} onClick={()=>start('project',p)}>Edit</button><button style={secondary} aria-label={`Delete ${p.name}`} onClick={()=>remove('projects',p.id)}><Trash2 size={14}/></button></div></article>)}</div>:<div className="phase2-empty"><Target size={20}/><b>No projects recorded.</b><span>Add a customer opportunity or business project to track its current stage.</span></div>}
    </Section>
    <Section title="Budgets & savings" eyebrow="USER-DEFINED TARGETS" actions={<button style={primary} onClick={()=>start('goal')}><Plus size={14}/> Add goal</button>}>
      {value.goals.length?<div className="phase2-goals">{value.goals.map(g=><article className="phase2-record" key={g.id}><div className="phase2-grow"><div className="phase2-split"><b>{g.name}</b><span>{new Intl.NumberFormat(undefined,{style:'currency',currency:g.currency}).format(g.saved)} / {new Intl.NumberFormat(undefined,{style:'currency',currency:g.currency}).format(g.target)}</span></div><div className="phase2-bar"><i style={{width:`${Math.min(100,g.target?g.saved/g.target*100:0)}%`}}/></div><small>Progress based on manually entered amounts · {g.currency}</small></div><div className="phase2-row-actions"><button style={secondary} onClick={()=>start('goal',g)}>Edit</button><button style={secondary} aria-label={`Delete ${g.name}`} onClick={()=>remove('goals',g.id)}><Trash2 size={14}/></button></div></article>)}</div>:<div className="phase2-empty"><Wallet size={20}/><b>Set a personal target.</b><span>Enter your own budget or savings progress; no financial advice or forecast is implied.</span></div>}
    </Section>
    <Section title="Spending limits" eyebrow="MANUAL CATEGORY BUDGETS" actions={<button style={primary} onClick={()=>start('budget')}><Plus size={14}/> Add budget</button>}>
      {value.budgets.length?<div className="phase2-goals">{value.budgets.map(b=>{const total=spent(b);return <article className="phase2-record" key={b.id}><div className="phase2-grow"><div className="phase2-split"><b>{b.name} <small>{b.period==='month'?'THIS MONTH':'ALL-TIME'}</small></b><span>{new Intl.NumberFormat(undefined,{style:'currency',currency:b.currency}).format(total)} / {new Intl.NumberFormat(undefined,{style:'currency',currency:b.currency}).format(b.amount)}</span></div><div className="phase2-bar"><i style={{width:`${Math.min(100,total/b.amount*100)}%`}}/></div><small>Matches expense entries with this exact category · {b.currency}</small></div><div className="phase2-row-actions"><button style={secondary} onClick={()=>start('budget',b)}>Edit</button><button style={secondary} aria-label={`Delete ${b.name} budget`} onClick={()=>remove('budgets',b.id)}><Trash2 size={14}/></button></div></article>})}</div>:<div className="phase2-empty"><Wallet size={20}/><b>No spending limits yet.</b><span>Set a category and currency; totals come only from matching manual expense entries.</span></div>}
    </Section>
    <Section title="Real-currency ledger" eyebrow="REVENUE & EXPENSES" actions={<button style={primary} onClick={()=>start('money')}><Plus size={14}/> Record entry</button>}>
      {transactions.length?<div className="phase2-ledger">{transactions.slice(0,8).map(t=><div key={t.id}><span>{t.category}<small>{new Date(t.at).toLocaleDateString()}</small></span><b className={t.type}>{t.type==='income'?'+':'−'}{new Intl.NumberFormat(undefined,{style:'currency',currency:t.currency}).format(t.amount)}</b></div>)}</div>:<div className="phase2-empty"><Wallet size={20}/><b>No business revenue or expenses yet.</b><span>Nothing is inferred from outside the entries you add.</span></div>}
      <div className="phase2-plain-note">Forecast: not shown. No assumptions have been provided for a forecast.</div>
    </Section>
    {notice&&<p role="status" className="phase2-save">{notice}</p>}
    {form&&<div className="phase2-dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setForm(null)}}><form className="phase2-dialog" onSubmit={save}><div className="eyebrow">LOCAL BUSINESS RECORD</div><h2 style={{...heading,fontSize:25,margin:'6px 0 18px'}}>{edit?'Edit':'Add'} {form==='money'?'ledger entry':form}</h2>
      {form==='customer'&&<><label className="field-label">Customer name<input required maxLength={80} style={fieldStyle} value={customerName} onChange={e=>setCustomerName(e.target.value)}/></label><label className="field-label spaced">Email, optional<input type="email" style={fieldStyle} value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="field-label spaced">Notes<textarea style={fieldStyle} value={note} onChange={e=>setNote(e.target.value)}/></label></>}
      {form==='project'&&<><label className="field-label">Project title<input required maxLength={90} style={fieldStyle} value={projectName} onChange={e=>setProjectName(e.target.value)}/></label><label className="field-label spaced">Customer<select style={fieldStyle} value={customerId} onChange={e=>setCustomerId(e.target.value)}><option value="">Unassigned</option>{value.customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field-label spaced">Sales stage<select style={fieldStyle} value={stage} onChange={e=>setStage(e.target.value)}>{stages.map(s=><option key={s}>{s}</option>)}</select></label><label className="field-label spaced">Optional budget amount<div className="phase2-input-pair"><input type="number" min="0" step=".01" style={fieldStyle} value={budget} onChange={e=>setBudget(e.target.value)} placeholder="0.00"/><select style={fieldStyle} value={currency} onChange={e=>setCurrency(e.target.value)}>{currencies.map(c=><option key={c}>{c}</option>)}</select></div></label><label className="field-label spaced">Notes<textarea style={fieldStyle} value={note} onChange={e=>setNote(e.target.value)}/></label></>}
      {form==='goal'&&<><label className="field-label">Goal name<input required style={fieldStyle} value={goalName} onChange={e=>setGoalName(e.target.value)}/></label><label className="field-label spaced">Target amount<input required type="number" min=".01" step=".01" style={fieldStyle} value={target} onChange={e=>setTarget(e.target.value)}/></label><label className="field-label spaced">Amount saved so far<input type="number" min="0" step=".01" style={fieldStyle} value={saved} onChange={e=>setSaved(e.target.value)}/></label><label className="field-label spaced">Currency<select style={fieldStyle} value={currency} onChange={e=>setCurrency(e.target.value)}>{currencies.map(c=><option key={c}>{c}</option>)}</select></label></>}
      {form==='budget'&&<><label className="field-label">Expense category<input required style={fieldStyle} value={budgetCategory} onChange={e=>setBudgetCategory(e.target.value)} placeholder="Must match a ledger category"/></label><label className="field-label spaced">Limit amount<input required type="number" min=".01" step=".01" style={fieldStyle} value={budgetLimit} onChange={e=>setBudgetLimit(e.target.value)}/></label><label className="field-label spaced">Period<select style={fieldStyle} value={budgetPeriod} onChange={e=>setBudgetPeriod(e.target.value as typeof budgetPeriod)}><option value="month">This calendar month</option><option value="all-time">All time</option></select></label><label className="field-label spaced">Currency<select style={fieldStyle} value={currency} onChange={e=>setCurrency(e.target.value)}>{currencies.map(c=><option key={c}>{c}</option>)}</select></label><p className="form-note">Actual totals use expense entries whose category matches exactly. This is a tracking limit, not a forecast.</p></>}
      {form==='money'&&<><div className="type-switch"><button type="button" className={moneyType==='income'?'active':''} onClick={()=>setMoneyType('income')}>Revenue</button><button type="button" className={moneyType==='expense'?'active':''} onClick={()=>setMoneyType('expense')}>Expense</button></div><label className="field-label">Amount<input required type="number" min=".01" step=".01" style={fieldStyle} value={moneyAmount} onChange={e=>setMoneyAmount(e.target.value)}/></label><label className="field-label spaced">Currency<select style={fieldStyle} value={currency} onChange={e=>setCurrency(e.target.value)}>{currencies.map(c=><option key={c}>{c}</option>)}</select></label><label className="field-label spaced">Category<input required style={fieldStyle} value={category} onChange={e=>setCategory(e.target.value)}/></label><label className="field-label spaced">Note<input style={fieldStyle} value={note} onChange={e=>setNote(e.target.value)}/></label></>}
      <div className="data-button-row"><button type="button" style={secondary} onClick={()=>setForm(null)}>Cancel</button><button type="submit" style={primary}>Save locally <ArrowRight size={14}/></button></div>
    </form></div>}
  </div>;
}

function English({value,onChange,onLessonXp}:Pick<Props,'value'|'onChange'|'onLessonXp'>) {
  const [search,setSearch]=useState(''); const [selected,setSelected]=useState<string|null>(null); const [mode,setMode]=useState<'lesson'|'cards'|'quiz'>('lesson'); const [flipped,setFlipped]=useState(false); const [cardIndex,setCardIndex]=useState(0); const [quizChoice,setQuizChoice]=useState(''); const [quizResult,setQuizResult]=useState('');
  const found=words.filter(x=>x.word.toLowerCase().includes(search.toLowerCase()));
  const lesson=words.find(x=>x.word===selected);
  const update=(word:string,progress:LessonProgress)=>onChange({...value,lessons:{...value.lessons,[word]:progress}});
  const progress=lesson?value.lessons[lesson.word]||{reviewed:false,mastered:false,correct:0,attempts:0}:null;
  const begin=(word:string)=>{setSelected(word);setMode('lesson');setQuizChoice('');setQuizResult('');setFlipped(false);};
  const assessment=(answer:string)=>{if(!lesson||!progress)return;const good=answer.trim().toLowerCase()===lesson.answer.toLowerCase();const next={...progress,reviewed:true,attempts:progress.attempts+1,correct:progress.correct+(good?1:0),mastered:progress.mastered||good,...(good&&!progress.mastered?{completedAt:new Date().toISOString()}: {})};if(good&&!progress.mastered)onLessonXp(lesson.word,lesson.xp);update(lesson.word,next);setQuizResult(good?'Correct. Mastery recorded locally; your reward is earned once.':'Not quite. Revisit the lesson, then try again.');};
  const flash=words[cardIndex%words.length];
  return <div>
    <div className="phase2-note"><BookOpen size={15}/> Word histories are concise learning notes, not claims of certainty. Each source link opens the corresponding Etymonline entry.</div>
    <div className="phase2-library">
      <aside className="phase2-library-side"><label className="phase2-search"><Search size={15}/><input aria-label="Search lesson library" placeholder="Find a word" value={search} onChange={e=>setSearch(e.target.value)}/></label><div className="phase2-word-list">{found.map(w=><button key={w.word} className={selected===w.word?'active':''} onClick={()=>begin(w.word)}><span>{w.word}</span><small>{value.lessons[w.word]?.mastered?'MASTERED':value.lessons[w.word]?.reviewed?'REVIEWED':'LESSON'}</small></button>)}{!found.length&&<p className="muted-note">No matching lesson. Try another word.</p>}</div></aside>
      <main className="phase2-lesson-area">{lesson&&progress?<><div className="phase2-mode-tabs">{(['lesson','cards','quiz'] as const).map(m=><button className={mode===m?'active':''} key={m} onClick={()=>{setMode(m);setQuizResult('');}}>{m==='lesson'?'Lesson':m==='cards'?'Flashcards':'Mastery check'}</button>)}</div>
        {mode==='lesson'?<article className="phase2-lesson"><div className="eyebrow">ENGLISH MAGICK · WORD {words.findIndex(w=>w.word===lesson.word)+1} OF 15</div><h2 style={{...heading,fontSize:38,margin:'8px 0'}}>{lesson.word}</h2><p className="phase2-definition">{lesson.definition}</p><div className="phase2-lesson-grid"><section><h3>Roots &amp; etymology</h3><p>{lesson.roots}</p></section><section><h3>Historical development</h3><p>{lesson.history}</p></section><section><h3>Practical meaning</h3><p>{lesson.practical}</p></section><section><h3>Application</h3><p>{lesson.application}</p></section><section><h3>Example</h3><p>{lesson.example}</p></section><section><h3>Exercise</h3><p>{lesson.exercise}</p></section></div><a className="phase2-source" href={`https://www.etymonline.com/word/${lesson.word.toLowerCase()}`} target="_blank" rel="noreferrer">Read source at Etymonline <ArrowRight size={13}/></a><div className="phase2-assess"><span>{progress.mastered?`Mastery earned · +${lesson.xp} XP`:'Assessment reward: '+lesson.xp+' XP once per word'}</span><button style={primary} onClick={()=>setMode('quiz')}>{progress.mastered?'Practice again':'Check mastery'} <ArrowRight size={13}/></button></div></article>:mode==='cards'?<div className="phase2-card-study"><div className="eyebrow">FLASHCARD {cardIndex+1} / {words.length}</div><button className={`phase2-flashcard ${flipped?'flipped':''}`} onClick={()=>setFlipped(!flipped)} aria-label={flipped?'Show word':'Show definition'}><small>{flipped?'DEFINITION':'WORD'}</small><b>{flipped?flash.definition:flash.word}</b><span>Tap to turn card</span></button><div className="phase2-card-controls"><button style={secondary} onClick={()=>{setCardIndex((cardIndex+words.length-1)%words.length);setFlipped(false)}}><ChevronLeft size={15}/> Previous</button><button style={secondary} onClick={()=>{setCardIndex((cardIndex+1)%words.length);setFlipped(false)}}>Next <ChevronRight size={15}/></button></div></div>:<div className="phase2-quiz"><div className="eyebrow">RECALL WITHOUT PEEKING</div><h3>{lesson.question}</h3><p>Choose the most accurate answer.</p>{[lesson.answer,...(lesson.answer.startsWith('Stretch')?['A fixed point in a plan','A promise that an outcome will happen']:['A modern meaning with no historical connection','A guaranteed result'])].map((a,i)=><button className={`phase2-answer ${quizChoice===a?'chosen':''}`} onClick={()=>setQuizChoice(a)} key={`${lesson.word}-${i}`}><span>{String.fromCharCode(65+i)}</span>{a}</button>)}<button style={primary} disabled={!quizChoice} onClick={()=>assessment(quizChoice)}>Submit answer <Check size={14}/></button>{quizResult&&<div role="status" className={`phase2-quiz-result ${quizResult.startsWith('Correct')?'good':''}`}>{quizResult}</div>}<p className="phase2-quiz-count">Attempts {progress.attempts} · correct {progress.correct}</p></div>}</>:<div className="empty-state"><div className="empty-emblem"><BookOpen size={21}/></div><h3>Choose a word to begin.</h3><p>Fifteen practical lessons, kept in your private local record.</p></div>}</main>
    </div>
    <Section title="Study without a schedule" eyebrow="YOUR LEARNING RECORD"><p className="muted-note">{Object.values(value.lessons).filter(p=>p.reviewed).length} reviewed · {Object.values(value.lessons).filter(p=>p.mastered).length} mastered. No streaks and no penalty for returning later.</p></Section>
  </div>;
}

function Training({value,onChange,quests,onTrainingComplete}:Pick<Props,'value'|'onChange'|'quests'|'onTrainingComplete'>) {
  const [form,setForm]=useState(false);const [editing,setEditing]=useState<string|null>(null);const [title,setTitle]=useState('');const [description,setDescription]=useState('');const [kind,setKind]=useState<'safe'|'boss'>('safe');const [attribute,setAttribute]=useState<TrainingAttribute>('Focus');const [target,setTarget]=useState('3');const [questId,setQuestId]=useState('');const [suggestion,setSuggestion]=useState('');
  const attributes:TrainingAttribute[]=['Strength','Endurance','Agility','Discipline','Reaction','Focus','Technique','General'];
  const suggestions:{title:string;kind:'safe'|'boss';attribute:TrainingAttribute;description:string;target:number}[]=[
    {title:'Take a 20-minute walk',kind:'safe',attribute:'Endurance',description:'Walk at a comfortable pace and adapt or stop if needed. One completed walk is one logged step.',target:1},
    {title:'Practice a strength movement',kind:'safe',attribute:'Strength',description:'If appropriate for you, do a comfortable strength movement or variation; stop or adapt if it does not feel safe.',target:1},
    {title:'Try a controlled footwork drill',kind:'safe',attribute:'Agility',description:'In a clear safe space, practice slow, controlled footwork with no contact.',target:1},
    {title:'Practice a reaction-time puzzle',kind:'safe',attribute:'Reaction',description:'Complete a short, non-contact reaction-time game or puzzle.',target:1},
    {title:'Complete a focus session',kind:'safe',attribute:'Focus',description:'Work on one chosen task for a short period without switching tasks.',target:1},
    {title:'Practice a safe movement',kind:'safe',attribute:'Technique',description:'Practice a gentle movement pattern in a safe space, within your comfort.',target:1},
    {title:'The Procrastination Boss',kind:'boss',attribute:'Discipline',description:'Start one real task you have been putting off and log the step you completed.',target:1},
    {title:'The Distraction Boss',kind:'boss',attribute:'Focus',description:'Choose one distraction to set aside and complete one focused work interval.',target:1},
    {title:'The Deadline Guardian',kind:'boss',attribute:'Discipline',description:'Break an upcoming deadline into one concrete next action and complete it.',target:1},
    {title:'The Interview Champion',kind:'boss',attribute:'Technique',description:'Prepare one interview response and practice it once, aloud or in writing.',target:1},
    {title:'The Knowledge Titan',kind:'boss',attribute:'Focus',description:'Study one chosen topic and complete one practice question or explanation.',target:1},
  ];
  const open=(challenge?:TrainingChallenge)=>{setEditing(challenge?.id||null);setTitle(challenge?.title||'');setDescription(challenge?.description||'');setKind(challenge?.kind||'safe');setAttribute(challenge?.attribute||'Focus');setTarget(String(challenge?.target||3));setQuestId(challenge?.linkedQuestId||'');setSuggestion('');setForm(true);};
  const save=(e:FormEvent)=>{e.preventDefault();const existing=value.training.find(c=>c.id===editing);const nextTarget=Math.max(1,Number(target)||1);const nowComplete=!!existing&&existing.progress>=nextTarget;const item:TrainingChallenge={id:existing?.id||makeId(),title:title.trim(),description:description.trim(),kind,attribute,target:nextTarget,progress:existing?.progress||0,linkedQuestId:questId,...(nowComplete?{completedAt:existing?.completedAt||new Date().toISOString()}:{})};onChange({...value,training:existing?value.training.map(c=>c.id===item.id?item:c):[item,...value.training]});if(nowComplete&&!existing?.completedAt&&item.linkedQuestId)onTrainingComplete(item.linkedQuestId);setEditing(null);setTitle('');setDescription('');setForm(false);};
  const progress=(c:TrainingChallenge,amount:number)=>{if(c.completedAt)return;const n=Math.min(c.target,c.progress+amount);const completedAt=n>=c.target?new Date().toISOString():undefined;onChange({...value,training:value.training.map(t=>t.id===c.id?{...t,progress:n,completedAt}:t)});if(completedAt&&c.linkedQuestId)onTrainingComplete(c.linkedQuestId);};
  const remove=(c:TrainingChallenge)=>{if(window.confirm(`Delete “${c.title}” from your training log?`))onChange({...value,training:value.training.filter(x=>x.id!==c.id)});};
  return <div><div className="phase2-note"><Shield size={15}/> Training is self-described task completion, not a medical measurement or a substitute for professional guidance. These attributes are practice categories; bosses are fictional metaphors and progress bars show logged steps only.</div>
    <Section title="Training attributes" eyebrow="PRACTICE CATEGORIES"><div className="phase2-attribute-grid">{attributes.map(name=><div className="phase2-attribute" key={name}><b>{name}</b><span>{value.training.filter(c=>(c.attribute||'General')===name).reduce((sum,c)=>sum+c.progress,0)} logged steps</span></div>)}</div></Section>
    <Section title="Training challenges" eyebrow="SAFE, SELF-DEFINED PRACTICE" actions={<button style={primary} onClick={()=>open()}><Plus size={14}/> New challenge</button>}>
      {value.training.length?<div className="phase2-training-list">{value.training.map(c=><article className="phase2-training" key={c.id}><div className="phase2-training-icon">{c.kind==='boss'?<Swords size={17}/>:<Target size={17}/>}</div><div className="phase2-grow"><div className="phase2-split"><div><b>{c.title}</b><small>{c.kind==='boss'?'FICTIONAL OBSTACLE BATTLE':'SAFE REAL-LIFE CHALLENGE'}{c.linkedQuestId?` · ${quests.find(q=>q.id===c.linkedQuestId)?.title||'Linked quest'}`:''}</small></div><span>{c.progress}/{c.target} steps</span></div><p>{c.description||'A challenge defined by you.'}</p><div className="phase2-bar"><i style={{width:`${Math.min(100,c.progress/c.target*100)}%`}}/></div>{c.completedAt&&<small className="phase2-done">Completed {new Date(c.completedAt).toLocaleDateString()}</small>}</div><div className="phase2-row-actions">{!c.completedAt&&<button style={primary} onClick={()=>progress(c,1)} aria-label={`Log one step for ${c.title}`}>Log step</button>}<button style={secondary} onClick={()=>open(c)} aria-label={`Edit ${c.title}`}>Edit</button><button style={secondary} aria-label={`Delete ${c.title}`} onClick={()=>remove(c)}><Trash2 size={14}/></button></div></article>)}</div>:<div className="phase2-empty"><Target size={20}/><b>Your training board is clear.</b><span>Define safe, achievable effort or a fictional obstacle and log progress one step at a time.</span></div>}
    </Section>
    <div className="phase2-note subtle"><CircleHelp size={15}/> A challenge can link to an active quest. Reaching its user-defined step target records that quest completion through the usual XP rule. No battle imagery represents real people or physical harm.</div>
    {form&&<div className="phase2-dialog-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget){setForm(false);setEditing(null)}}}><form className="phase2-dialog" onSubmit={save}><div className="eyebrow">{editing?'EDIT':'CREATE'} A TRAINING RECORD</div><h2 style={{...heading,fontSize:25,margin:'6px 0 18px'}}>A challenge of your choosing</h2>{!editing&&<label className="field-label">Optional suggested challenge<select style={fieldStyle} value={suggestion} onChange={e=>{const chosen=suggestions.find(item=>item.title===e.target.value);setSuggestion(e.target.value);if(chosen){setTitle(chosen.title);setKind(chosen.kind);setAttribute(chosen.attribute);setDescription(chosen.description);setTarget(String(chosen.target));}}}><option value="">Start with a blank challenge</option>{suggestions.map(item=><option key={item.title} value={item.title}>{item.title}</option>)}</select></label>}<label className="field-label spaced">Title<input required style={fieldStyle} value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Prepare for a difficult conversation"/></label><label className="field-label spaced">Type<select style={fieldStyle} value={kind} onChange={e=>setKind(e.target.value as typeof kind)}><option value="safe">Safe real-life challenge</option><option value="boss">Fictional obstacle / boss battle</option></select></label><label className="field-label spaced">Practice attribute<select style={fieldStyle} value={attribute} onChange={e=>setAttribute(e.target.value as TrainingAttribute)}>{attributes.filter(x=>x!=='General').map(x=><option key={x}>{x}</option>)}</select></label><label className="field-label spaced">What counts as one logged step?<textarea required style={fieldStyle} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Describe an objective, safe task." /></label><label className="field-label spaced">Number of steps<input type="number" min={Math.max(1,value.training.find(c=>c.id===editing)?.progress||1)} max="1000" required style={fieldStyle} value={target} onChange={e=>setTarget(e.target.value)}/></label><label className="field-label spaced">Connect to an active quest (optional)<select style={fieldStyle} value={questId} onChange={e=>setQuestId(e.target.value)}><option value="">No linked quest</option>{quests.filter(q=>q.status==='active').map(q=><option key={q.id} value={q.id}>{q.title}</option>)}</select></label><p className="form-note">Bars show logged steps only. This is not health, fitness, or clinical data.</p><div className="data-button-row"><button type="button" style={secondary} onClick={()=>{setForm(false);setEditing(null)}}>Cancel</button><button type="submit" style={primary}>{editing?'Save changes':'Create challenge'} <ArrowRight size={14}/></button></div></form></div>}
  </div>;
}

const scenarios=[
  {id:'listen',title:'A friend needs to talk',scene:'A fictional friend says they had a difficult day, then pauses. You are not sure whether they want advice.',options:[
    {text:'Ask whether they want listening, ideas, or a little space.',explain:'Checks what support would feel useful and leaves them choice.'},
    {text:'Immediately list solutions so the problem gets fixed.',explain:'May be helpful if advice is wanted, but can feel like being rushed past before being heard.'},
    {text:'Tell them their situation is not that serious.',explain:'Can minimize their experience and make openness feel less safe.'}]},
  {id:'boundary',title:'A request you cannot take on',scene:'A fictional teammate asks you to add work to a week that is already full.',options:[
    {text:'State your limit clearly and, if you wish, suggest an alternative.',explain:'Communicates a boundary while making room for a workable next step.'},
    {text:'Agree despite knowing you cannot follow through.',explain:'Avoids immediate discomfort but can create stress and unreliable expectations.'},
    {text:'Respond with a personal attack.',explain:'May escalate conflict and obscures the actual limit you need to communicate.'}]},
  {id:'repair',title:'A misunderstanding',scene:'A fictional person says your comment landed more sharply than you intended.',options:[
    {text:'Listen, ask what impact they noticed, and explain your intent without dismissing impact.',explain:'Balances curiosity and accountability; it does not require agreeing about every detail.'},
    {text:'Insist that good intent means no harm could have occurred.',explain:'Intent matters, but this may close the conversation about the other person’s experience.'},
    {text:'Pause and ask to return to the topic at a clear time.',explain:'A respectful pause can help if emotions are high, especially when you follow through.'}]},
  {id:'friendship',title:'Building a friendship',scene:'You enjoyed a conversation with a fictional acquaintance and would like to keep in touch.',options:[
    {text:'Offer a specific, low-pressure invitation and accept either answer.',explain:'Makes interest clear while respecting choice and uncertainty.'},
    {text:'Assume one good conversation guarantees a close friendship.',explain:'Closeness develops through mutual time and consent; a single moment cannot guarantee it.'},
    {text:'Send repeated messages until they reply.',explain:'Can put pressure on the other person. One invitation followed by space respects boundaries.'}]},
  {id:'relationship',title:'Talking about relationship pace',scene:'In a fictional new relationship, you and the other person seem to want different amounts of time together.',options:[
    {text:'Share what pace feels comfortable and invite them to share theirs.',explain:'Makes needs discussable and allows both people to decide whether there is a mutually workable pace.'},
    {text:'Treat closeness as something the other person owes you.',explain:'A relationship does not remove either person’s right to boundaries or choice.'},
    {text:'Assume you can infer their feelings without asking.',explain:'People’s preferences cannot be reliably scored or guessed from a single signal; respectful conversation is clearer.'}]},
];
function Social({value,onChange}:Pick<Props,'value'|'onChange'>) {
  const [active,setActive]=useState<string|null>(null);const [choice,setChoice]=useState<number|null>(null);
  const scenario=scenarios.find(s=>s.id===active);const completed=value.socialCompletions;
  const finish=()=>{if(!active)return;if(!completed.includes(active))onChange({...value,socialCompletions:[...completed,active]});setActive(null);setChoice(null);};
  return <div><div className="phase2-note"><Users size={15}/> Fictional practice only. These are reflection prompts, not predictions. No real person’s feelings, attraction, or response can be scored or guaranteed.</div>
    <Section title="Conversation practice" eyebrow="FICTIONAL SCENARIOS"><p className="muted-note">Choose a response to reveal a plain-language reflection. Multiple responses can be understandable in context; the notes describe possibilities, not guaranteed outcomes.</p>
      {scenario?<div className="phase2-scenario"><button className="text-link" onClick={()=>{setActive(null);setChoice(null)}}><ChevronLeft size={14}/> All scenarios</button><h3>{scenario.title}</h3><p>{scenario.scene}</p><div className="phase2-options">{scenario.options.map((o,i)=><button key={o.text} className={`phase2-option ${choice===i?'chosen':''}`} onClick={()=>setChoice(i)}>{o.text}</button>)}</div>{choice!==null&&<div className="phase2-explanation" role="status"><b>One possible implication</b><p>{scenario.options[choice].explain}</p><button style={primary} onClick={finish}>{completed.includes(scenario.id)?'Close practice':'Record reflection'} <Check size={14}/></button></div>}</div>:<div className="phase2-record-grid">{scenarios.map(s=><article className="phase2-record scenario-card" key={s.id}><div><b>{s.title}</b><p>{s.scene}</p></div><div className="phase2-row-actions"><small>{completed.includes(s.id)?'PRACTICED':'NOT STARTED'}</small><button style={secondary} onClick={()=>{setActive(s.id);setChoice(null)}}>{completed.includes(s.id)?'Practice again':'Begin'}</button></div></article>)}</div>}
    </Section><div className="phase2-plain-note">Progress means you completed a reflection exercise. It does not measure social skill, another person’s feelings, or likely relationship success.</div>
  </div>;
}
